#!/bin/sh
# Channel state queries with NOPs: (0,dst,LAST) is the read side,
# (0,LAST,src) is the write side; the query writes an 8-bit state
# byte (bit 0 of the byte means end of input seen / output failure;
# the byte is not required to sit on a byte boundary).
# Program: query, input, query, output, output, query, output + 'Q'.
# Tick 1: load (silence); tick 2: all zero except the input 'Q';
# tick 3: the second query sees the end; tick 4: both queries see the
# end. Outward: 00 00 00 | 00 01 00 | 01 01 00.
set -e
cd "$(dirname "$0")/.."
if [ ! -x ./space ]; then
  echo "no ./space, run make first"
  exit 1
fi
{ printf '\000\000\000\011\357\376\040\000\040\023\337\374\000\000\020\047\277\370\200\017\177\360\000\101\000\036\377\340\100\200\000\075\377\303\001\004\000\173\377\206\002\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000'; printf 'Q'; } | timeout 5 ./space -t 4 > /tmp/state_run.out
printf '\000\000\000\000\001\000\001\001\000' > /tmp/state_expected.out
cmp /tmp/state_run.out /tmp/state_expected.out
echo "ok: state queries see the end (00 00 00, 00 01 00, 01 01 00)"
